    game: &mut crate::game::Game<'_>,
    context: &ExplosionHookContext<'_>,
    radius: f32,
    damage_type: &str,
    exploding: Option<u32>,
    attacker: Option<&(u32, Text)>,
    cause: Option<&horizon_client::advancements::EntityView>,
) -> std::ops::ControlFlow<Option<[f64; 3]>> {
